using System;
using System.Collections.Generic;
using UnityEngine;
using NursingQuiz.Core;

namespace NursingQuiz.Data
{
    [Serializable]
    public class MatchPairEntry
    {
        public string left;
        public string right;
    }

    /// <summary>
    /// One "Yhdistä oikein" round: a set of left/right pairs the player connects,
    /// plus shared feedback shown once the round is complete.
    /// Generated by MatchPairImporter -- one asset per source CSV file.
    ///
    /// Unlike QuestionData (which has per-question feedback for a whole bank of alternatives),
    /// this content structure has ONE fixed set of pairs per file, with ONE shared feedback
    /// block for completing the whole exercise -- matching how the source material is written.
    /// </summary>
    public class MatchPairSet : ScriptableObject
    {
        [Header("Identity")]
        public string category;
        public string theme;
        public DifficultyTier tier;
        public string sourceFileName;

        [Header("Content")]
        public string gameName;

        [TextArea(2, 6)]
        public string oppimistavoite;

        public List<MatchPairEntry> pairs = new List<MatchPairEntry>();

        [Header("Feedback (shown once all pairs are matched)")]
        [TextArea(1, 4)] public string completionFeedback;
        [TextArea(1, 4)] public string professionalPatch;
    }
}
